using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;

public static class GridShiftTutorial {
 public static string Prefix="GS.Tutorial.";
 static TutorialSaveData state=new TutorialSaveData{version=2,extraHints=true};static PlayerMovement observed;static Vector3 lastPosition;static Quaternion lastLook;
 public static int Step=>Mathf.Clamp(state.step,0,15);public static bool Completed=>state.complete;public static bool Skipped=>state.skipped;public static bool Active=>!Completed&&!Skipped;public static bool Greeted=>state.greeted;public static bool ExtraHints=>state.extraHints;public static string OrderId=>state.orderId;
 public static readonly string[] Titles={"Bem-vindo ao GridShift","Aprenda a se movimentar","Conheça Carlos","Sua central portátil","Visite a Factory","Fale com o atendente","Consulte seu pedido","Encontre a caixa","Confira a encomenda","Prepare e saia com a caixa","Carregue sua encomenda","Sua primeira viagem","Estacione e descarregue","Entregue ao cliente","Conheça as finanças","Salve seu progresso"};
 public static string[] Instructions()=>new[]{"Você está começando uma transportadora. Faça entregas, conquiste clientes e amplie a empresa.","Use "+Keys()+" e o mouse para olhar. Caminhe e segure "+GridShiftControls.KeyName(GSAction.Run)+" para correr.","Siga o marcador até Carlos e pressione "+GridShiftControls.KeyName(GSAction.Interact)+" quando aparecer a ação.","Abra o tablet com "+GridShiftControls.KeyName(GSAction.Tablet)+" e selecione a aba Entregas.","Siga o marcador Factory. Na porta, use "+GridShiftControls.KeyName(GSAction.Interact)+" para entrar no centro de distribuição.","Procure a recepção à esquerda. Converse com o funcionário e encerre a conversa.","Consulte o terminal de pedidos na expedição e aceite uma encomenda pequena.","Vá ao setor indicado. Confira o ID do pedido e pegue a caixa indicada com "+GridShiftControls.KeyName(GSAction.Interact)+".","Leve a caixa à mesa de conferência. Olhe para o leitor e confirme o código.","Na embalagem, use o tamanho indicado. Depois siga a saída levando a encomenda.","Vá até a traseira da van. Pressione "+GridShiftControls.KeyName(GSAction.Interact)+" para abrir o compartimento. Depois, pressione a mesma tecla para guardar a caixa.","Entre pela porta lateral. Dirija com "+Keys()+", olhe com o mouse e consulte a rota com "+GridShiftControls.KeyName(GSAction.Map)+".","Estacione perto do destino. Saia com a van parada e retire a caixa do compartimento.","Leve a caixa até a entrada marcada do cliente e use "+GridShiftControls.KeyName(GSAction.Interact)+". O pagamento depende da entrega real.","Abra o tablet e visite Financeiro. Veja o saldo, receitas, despesas e contas existentes.","Salve pelo menu de pausa. Se o autosave já ocorreu, seu progresso já está protegido."};
 static string Keys()=>GridShiftControls.KeyName(GSAction.Forward)+" / "+GridShiftControls.KeyName(GSAction.Back)+" / "+GridShiftControls.KeyName(GSAction.Left)+" / "+GridShiftControls.KeyName(GSAction.Right);
 public static TutorialSaveData Capture()=>JsonUtility.FromJson<TutorialSaveData>(JsonUtility.ToJson(state));
 public static void Restore(TutorialSaveData saved,bool fresh=false){bool scoped=GridShiftProfiles.LoggedIn&&GridShiftProfiles.ActiveSlot>0&&Prefix.StartsWith("GS.Tutorial."+GridShiftProfiles.ProfileId+"."+GridShiftProfiles.ActiveSlot+".Partida.");bool completed=!fresh&&scoped&&PlayerPrefs.GetInt(Prefix+"Complete",0)==1;bool skipped=!fresh&&scoped&&PlayerPrefs.GetInt(Prefix+"Skipped",0)==1;state=saved!=null&&saved.version>=2?JsonUtility.FromJson<TutorialSaveData>(JsonUtility.ToJson(saved)):new TutorialSaveData{version=2,extraHints=true,complete=saved?.complete??false,skipped=saved?.skipped??false,completionAcknowledged=saved?.complete??false};if(completed||state.complete){state.complete=true;state.skipped=false;state.completionAcknowledged=true;}else if(skipped)state.skipped=true;if(fresh){PlayerPrefs.SetInt(Prefix+"Complete",0);PlayerPrefs.SetInt(Prefix+"Skipped",0);}if(scoped&&state.complete)PlayerPrefs.SetInt(Prefix+"Complete",1);state.step=Mathf.Clamp(state.step,0,15);observed=null;GridShiftTutorialGuide.ResetSession();}
 static void Changed(){PlayerPrefs.SetInt(Prefix+"Step",Step);PlayerPrefs.SetInt(Prefix+"Complete",Completed?1:0);PlayerPrefs.SetInt(Prefix+"Skipped",Skipped?1:0);DeliveryManager.Instance?.GetComponent<DeliveryPersistence>()?.RequestSave();}
 public static void Begin(){state.welcomed=true;Next();}
 public static void Skip(){state.skipped=true;Changed();}
 public static void Reopen(){bool greeted=state.greeted;state=new TutorialSaveData{version=2,extraHints=true,greeted=greeted};observed=null;Changed();}
 public static void ToggleHints(){state.extraHints=!state.extraHints;Changed();}
 public static void Acknowledge(){state.completionAcknowledged=true;Changed();}
 public static bool NeedsCompletion=>Completed&&!state.completionAcknowledged;
 public static void BindOrder(string id){if(Active&&Step<=6){state.orderId=id;Changed();}}
 public static void Record(string action){if(action=="save"){state.anySaved=true;return;}if(action=="attendant"){state.greeted=true;state.talked=true;Changed();}if(!Active)return;if(action=="interact"&&Step==2)state.interacted=true;if(action=="deliveries-tab"&&Step==3)state.tabletViewed=true;if(action=="terminal"&&Step==6)state.terminalViewed=true;if(action=="map"&&Step==11)state.mapViewed=true;if(action=="finance"&&Step==14)state.financeViewed=true;Changed();}
 public static DeliveryOrder Order=>DeliveryManager.Instance?.orders.FirstOrDefault(o=>o.id==state.orderId);
 public static bool Satisfied(){var m=DeliveryManager.Instance;var ops=m?.GetComponent<GridShiftActiveOperations>();var o=Order;switch(Step){case 0:return state.welcomed;case 1:return state.walked>=2&&state.ran>=1&&state.looked>=10;case 2:return state.interacted;case 3:return state.tabletViewed;case 4:return WorldSession.Instance!=null&&WorldSession.Instance.InFactory;case 5:return state.talked;case 6:return state.terminalViewed&&o!=null;case 7:return o!=null&&(o.depotPicked||!o.depotRequired&&o.status!=DeliveryStatus.ToPickup);case 8:return o!=null&&(o.depotScanned||!o.depotRequired&&o.status!=DeliveryStatus.ToPickup);case 9:return o!=null&&(o.depotReleased||!o.depotRequired&&o.status!=DeliveryStatus.ToPickup)&&SceneManager.GetActiveScene().name=="SampleScene";case 10:return o!=null&&ops?.Van?.CargoOrderId==o.id;case 11:return o!=null&&o.personalDrivenMeters>=3&&ops?.Van?.Driving==true&&state.mapViewed;case 12:return o!=null&&ops?.Van!=null&&!ops.Van.Driving&&ops.Van.Speed<.3f&&Vector3.Distance(ops.Van.transform.position,m.Point(o.destinationId).Stop)<18&&string.IsNullOrEmpty(ops.Van.CargoOrderId);case 13:return o!=null&&o.status==DeliveryStatus.Completed&&o.rewardPaid;case 14:return state.financeViewed;case 15:return state.anySaved;}return false;}
 public static void Next(){if(!Active||!Satisfied())return;if(Step==15){state.complete=true;state.skipped=false;}else state.step++;GridShiftAudio.Play("UI_Confirm","UI",.3f);Changed();}
 public static void Observe(PlayerMovement player,bool mapSeen,bool controlsSeen){if(!Active||player==null||WorldSession.Instance!=null&&WorldSession.Instance.Busy)return;if(observed!=player){observed=player;lastPosition=player.transform.position;lastLook=player.CameraTransform.rotation;}if(Step==1&&!player.ControlsBlocked){float moved=Vector3.ProjectOnPlane(player.transform.position-lastPosition,Vector3.up).magnitude;if(moved<3&&player.MovementInput.sqrMagnitude>.05f){state.walked+=moved;if(player.IsRunning)state.ran+=moved;}state.looked+=Mathf.Min(30,Quaternion.Angle(lastLook,player.CameraTransform.rotation));}lastPosition=player.transform.position;lastLook=player.CameraTransform.rotation;if(Step==3&&player.GetComponent<PortableTablet>()?.IsOpen==true&&player.GetComponent<PortableTablet>().Operations?.CurrentPage=="Entregas")state.tabletViewed=true;if(Step==6&&string.IsNullOrEmpty(state.orderId)&&DeliveryManager.Instance?.PersonalOrder!=null)BindOrder(DeliveryManager.Instance.PersonalOrder.id);Next();}
 public static bool TryObjective(out Vector3 at,out string name){at=Vector3.zero;name="";if(!Active||Step==0||Step==1||Step==3||Step>=14)return false;var m=DeliveryManager.Instance;var ops=m?.GetComponent<GridShiftActiveOperations>();if(ops==null||ops.Config==null)return false;var inside=WorldSession.Instance!=null&&WorldSession.Instance.InFactory;var interior=GridShiftFactoryInterior.Instance;var o=Order;
  if(Step==2){if(GridShiftTutorialGuide.IntroBoard==null)return false;at=GridShiftTutorialGuide.IntroBoard.position;name="Carlos · Mentor";return true;}if(Step==4||!inside&&Step>=5&&Step<=8&&(o==null||o.depotRequired)){at=ops.Config.depotPosition;name="Factory · Centro de distribuição";return true;}if(Step==5&&interior!=null){at=interior.attendantPoint.position;name="Recepção · Atendente";return true;}if(Step==6&&interior!=null){at=ops.StationPosition("accept");name="Terminal de pedidos";return true;}if(inside&&o!=null&&!o.depotRequired&&Step>=7&&Step<=9){at=interior.exitPoint.position;name="Saída · Continue seu pedido atual";return true;}if(Step==7&&o!=null){at=ops.Origin(o);name="Caixa #"+o.id.Substring(0,8)+" · Setor "+(o.weightKg<=5?"A":"B");return true;}if(Step==8&&interior!=null){at=ops.StationPosition("scan");name="Mesa de conferência";return true;}if(Step==9&&interior!=null){string command=o==null||!o.depotPacked?(o!=null&&o.weightKg>5?"pack-medium":"pack-small"):!o.depotLabelled?"label":!o.depotSorted?(ops.RequiredZone(o)==0?"sort-a":"sort-b"):!o.depotReleased?"release":"exit";at=command=="exit"?interior.exitPoint.position:ops.StationPosition(command);name=command=="exit"?"Saída · Leve a caixa":command=="label"?"Imprimir etiqueta":command.StartsWith("sort")?"Separar no setor "+(command=="sort-a"?"A":"B"):command=="release"?"Liberar expedição":command=="pack-medium"?"Embalagem média":"Embalagem pequena";return true;}if(Step==10&&ops.Van!=null){at=ops.Van.CargoPosition;name="Van · Compartimento de carga";return true;}if(o!=null&&Step>=11&&Step<=13){at=m.Point(o.destinationId).pedestrianAccess!=null?m.Point(o.destinationId).pedestrianAccess.position:m.Point(o.destinationId).Stop;name="Cliente · "+m.Point(o.destinationId).displayName;if(Step==12&&ops.Van!=null&&!string.IsNullOrEmpty(ops.Van.CargoOrderId)&&Vector3.Distance(ops.Van.transform.position,at)<18){at=ops.Van.CargoPosition;name="Retire a encomenda da van";}return true;}return false;
 }
}
